import calendar_joint_reference_candidate as _ENTRY
import joint_one_second_guard as _total_guard
_total_guard._startup_started=_guard_import_started
def _completed_day_action(obs):
    import copy
    step=int(obs['step']);day,hour=divmod(step,24);seat=int(obs['player'])
    planner=_ENTRY.N.P
    plans=getattr(planner,'plans',[])
    # Never replay yesterday's plan or an unrelated whole-game route.
    if not plans or plans[-1].get('day')!=day:return None
    actions=planner.state.get(seat)
    if not actions:return None
    action=copy.deepcopy(actions[hour])
    action['hands']=action.get('hands',[])[:len(obs['farms'][seat].get('hands',[]))]
    # Preserve completed physical work, retaining inputs for its remaining day.
    reserved={}
    for later in actions[hour+1:]:
        for cmd in [later.get('farmer'),*later.get('hands',[])]:
            if cmd and len(cmd)>=3 and cmd[0]=='PICKUP':reserved[cmd[1]]=reserved.get(cmd[1],0)+cmd[2]
    existing={o[1] for o in action.get('market',[]) if o and len(o)>1 and o[0]=='SELL'}
    action.setdefault('market',[])
    for p,q in obs['private']['shed'].items():
        if p in existing or p in ('WHEAT','FERTILIZER'):continue
        amount=max(0,q-reserved.get(p,0))
        if amount and len(action['market'])<10:action['market'].append(['SELL',p,amount])
    return action
agent=_total_guard.wrap(_ENTRY.agent,_completed_day_action)
agent.telemetry=_ENTRY.agent.telemetry
# Kaggle selects the final callable.
agent=globals().pop('agent')
